]]
-- The katana swings are heavier (longer wind-up and follow-through, see
-- KatanaAnimations WEIGHT), so its hitstun is a little longer too and the
-- strings still combo. Its hits also freeze a bit longer on impact.
Config.KatanaHitStopMult = 1.35
Config.Weapons = {
	Katana = {
		M1_1 = { range = 8, width = 6.5, hitstun = 0.43 },
		M1_2 = { range = 8, width = 6.5, hitstun = 0.43 },
		M1_3 = { range = 8, width = 7.5, hitstun = 0.47 },
		M1_4 = { range = 8.5, width = 5.5, hitstun = 0.52 },
		Finisher = { range = 8.5, width = 8 },
		Uppercut = { range = 7.5, width = 5.5 },
		AirPunch = { range = 8, width = 6.5, hitstun = 0.35 },
		AirKick = { range = 8, width = 7.5, hitstun = 0.35 },
		Downslam = { range = 8, width = 6.5 },
		Critical = { range = 9.5, width = 7 },
	},
}

-- Air strings use the current M1 clips, with the existing air hit rules.
for i, groundKind in ipairs(Config.M1Chain) do
	local airKind = Config.AirChain[i]
	local oldAirKind = i % 2 == 1 and "AirPunch" or "AirKick"
	local airAttack = table.clone(Config.Attacks[oldAirKind])
	airAttack.anim = Config.Attacks[groundKind].anim
	airAttack.react = Config.Attacks[groundKind].react
	Config.Attacks[airKind] = airAttack

	for _, weaponAttacks in pairs(Config.Weapons) do
		if weaponAttacks[oldAirKind] then
			weaponAttacks[airKind] = table.clone(weaponAttacks[oldAirKind])
		end
	end
end

local mergedAttacks = {}
-- Server-authored admin overrides never modify shared attack definitions.
function Config.damageFor(model, defaultDamage)
	local override = model and model:GetAttribute("AdminDamageOverride")
	if typeof(override) == "number" and override == override and override >= 0 and override < math.huge then
		return override
	end
	return defaultDamage
end

local function withAdminDamage(attack, model)
	if not attack then return nil end
	local damage = Config.damageFor(model, attack.damage)
	if damage == attack.damage then return attack end
	local adjusted = table.clone(attack)
	adjusted.damage = damage
	return adjusted
end

function Config.attackFor(kind, model)
	local base = Config.Attacks[kind]
	-- only while it's drawn: sheathed, you're swinging fists
	local weapon = model and model:GetAttribute("KatanaDrawn") == true and model:GetAttribute("Weapon")
	local overrides = weapon and Config.Weapons[weapon] and Config.Weapons[weapon][kind]
	if not base or not overrides then
		return withAdminDamage(base, model)
	end
	local key = weapon .. ":" .. kind
	local merged = mergedAttacks[key]
	if not merged then
		merged = table.clone(base)
		for k, v in pairs(overrides) do
			merged[k] = v
		end
		mergedAttacks[key] = merged
	end
	return withAdminDamage(merged, model)
end

return Config
]===]

SOURCES.Motion = [===[
-- Short movement bursts (lunges, dashes, knockback). Runs wherever the
-- character's physics is owned: the client for players, the server for NPCs.

local RunService = game:GetService("RunService")
local Config = require(script.Parent.Config)

local DASH_STEER_RATE = 9
local DASH_MIN_SPEED = 14
local ORBIT_MIN_RADIUS = 4 -- only pushes you out if you start almost inside them
local ORBIT_SIDEWAYS = 0.65 -- how sideways (relative to them) a dash must be to strafe around them
local ORBIT_MAX_ANGLE = math.rad(100) -- the most one strafe can carry you around someone
--
local Motion = {}
--boi.
-- horizontal part of a world vector (positions/velocities can have height)
local function flat(v)
	return Vector3.new(v.X, 0, v.Z)
end

-- 90 degrees around the vertical axis. Same as v:Cross(Vector3.yAxis) for a
-- flat v, and horizontal by construction, so it never needs flattening again.
local function perp(v)
	return Vector3.new(-v.Z, 0, v.X)
end

local function getAttachment(root)
	local attachment = root:FindFirstChild("CombatAttachment")
	if not attachment then
		attachment = Instance.new("Attachment")
		attachment.Name = "CombatAttachment"
		attachment.Parent = root
	end
	return attachment
end

local function makePush(root, planeVelocity)
	local push = Instance.new("LinearVelocity")
	push.Name = "CombatPush"
	push.Attachment0 = getAttachment(root)
	push.RelativeTo = Enum.ActuatorRelativeTo.World
	push.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
	push.PrimaryTangentAxis = Vector3.xAxis
	push.SecondaryTangentAxis = Vector3.zAxis
	push.PlaneVelocity = planeVelocity
	push.MaxForce = 1e5
	push.Parent = root
	return push
end

function Motion.stop(root)
	local existing = root:FindFirstChild("CombatPush")
	if existing then
		existing:Destroy()
	end
end

-- Constant push for `duration`, plus an optional vertical launch.
function Motion.push(root, velocity, duration)
	Motion.stop(root)

	local horizontal = Vector2.new(velocity.X, velocity.Z)
	if horizontal.Magnitude > 0.01 and duration > 0 then
		local push = makePush(root, horizontal)
		task.delay(duration, function()
			if push.Parent then
				push:Destroy()
			end
		end)
	end

	if velocity.Y ~= 0 then
		local humanoid = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
		if humanoid and velocity.Y > 0 then
			humanoid:ChangeState(Enum.HumanoidStateType.Freefall)
		end
		local current = root.AssemblyLinearVelocity
		root.AssemblyLinearVelocity = Vector3.new(current.X, velocity.Y, current.Z)
	end
end

-- Knockback loses speed across the whole stun, easing gently to a stop.
-- Keep this separate from lunges, small hit pushes and dash steering.
function Motion.knockback(root, velocity, duration)
	Motion.push(root, velocity, 0) -- clear the previous push and apply vertical launch
	local horizontal = Vector2.new(velocity.X, velocity.Z)
	if horizontal.Magnitude < 0.01 or duration <= 0 then
		return
	end

	local push = makePush(root, horizontal)
	local started = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function()
		if not push.Parent then
			connection:Disconnect()
			return
		end
		local alpha = math.clamp((os.clock() - started) / duration, 0, 1)
		push.PlaneVelocity = horizontal * (1 - alpha) ^ 2
		if alpha >= 1 then
			connection:Disconnect()
			push:Destroy()
		end
	end)
end

-- A burst that starts fast and eases out. A straight dash can be steered a
-- little with the movement keys. With `orbit` (a target's root part), a
-- sideways dash becomes a strafe arc around them instead: same distance and
-- timing as a straight dash, held at your starting distance from them, and
-- never more than ORBIT_MAX_ANGLE around however close you are. The camera
-- is turned in CombatClient, together with your facing.
function Motion.dash(root, velocity, duration, orbit)
	Motion.stop(root)

	local speed = flat(velocity).Magnitude
	if speed < 0.01 or duration <= 0 then
		return
	end
	local direction = flat(velocity).Unit
	local humanoid = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
	local push = makePush(root, Vector2.new(direction.X, direction.Z) * speed)

	local function speedAt(alpha)
		return math.max(DASH_MIN_SPEED, speed * (1 - alpha) ^ 1.6)
	end

	-- decide once, at the start, whether this is a strafe around someone
	local orbitSign, orbitRadius, orbitScale
	if orbit then
		local offset = flat(orbit.Position - root.Position)
		if offset.Magnitude > Config.DashOrbitMinRange and math.abs(direction:Dot(offset.Unit)) < ORBIT_SIDEWAYS then
			orbitSign = direction:Dot(perp(offset.Unit)) >= 0 and 1 or -1
			orbitRadius = math.max(offset.Magnitude, ORBIT_MIN_RADIUS)
			-- how far a straight dash would go, then fit that to an arc
			local distance = 0
			for i = 0, 19 do
				distance += speedAt((i + 0.5) / 20) * duration / 20
			end
			local arc = math.min(distance / orbitRadius, ORBIT_MAX_ANGLE)
			orbitScale = arc * orbitRadius / distance -- <= 1: close up, you slow down instead of looping
		end
	end

	local start = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function(dt)
		local alpha = (os.clock() - start) / duration
		if alpha >= 1 or not push.Parent then
			connection:Disconnect()
			if push.Parent then
				push:Destroy()
			end
			return
		end

		-- Keep the same speed easing when orbit assist drops out.
		local current = speedAt(alpha) * (orbitScale or 1)
		local offset = orbitSign and orbit.Parent and flat(orbit.Position - root.Position)
		if orbitSign and (not offset or offset.Magnitude <= Config.DashOrbitMinRange) then
			orbitSign = nil -- stay a straight dash for the rest of this burst
			offset = nil
		end
		if offset then
			-- along the circle, with a gentle pull back onto the starting radius
			local radial = offset.Unit
			local tangent = perp(radial) * orbitSign
			local correction = math.clamp((offset.Magnitude - orbitRadius) * 1.2, -0.6, 0.6)
			direction = (tangent + radial * correction).Unit
		elseif not orbitSign and humanoid then
			-- straight dash: the movement keys can bend it a little
			local move = flat(humanoid.MoveDirection)
			if move.Magnitude > 0.1 then
				local blended = direction:Lerp(move.Unit, math.min(1, dt * DASH_STEER_RATE))
				if blended.Magnitude > 0.05 then
					direction = blended.Unit
				end
			end
		end
		push.PlaneVelocity = Vector2.new(direction.X, direction.Z) * current
	end)
end

------------------------------------------------------------------------
-- Rush (Lumen Rush's dash): covers exactly `displacement` (horizontal) in
-- `duration`, on a curve with a hard but visible acceleration out of the
-- launch, a peak about a quarter of the way in, and a long braking glide
-- that settles the body where the cut lands, without sliding past it.
-- v(u) ~ u^A (1 - u)^B, the same curve tools/katana/motionprofile.py uses.

local RUSH_A, RUSH_B, RUSH_STEPS = 0.5, 1.4, 256
local rushTotal = 0
for i = 0, RUSH_STEPS - 1 do
	local u0, u1 = i / RUSH_STEPS, (i + 1) / RUSH_STEPS
	rushTotal += ((u0 ^ RUSH_A) * (1 - u0) ^ RUSH_B + (u1 ^ RUSH_A) * (1 - u1) ^ RUSH_B) / 2 / RUSH_STEPS
end

function Motion.rush(root, displacement, duration)
	Motion.stop(root)
	local flatMove = flat(displacement)
	local distance = flatMove.Magnitude
	if distance < 0.05 or duration <= 0 then
		return
	end
	local direction = flatMove.Unit
	local push = makePush(root, Vector2.zero)
	local start = os.clock()
	local connection
	connection = RunService.Heartbeat:Connect(function()
		local u = (os.clock() - start) / duration
		if u >= 1 or not push.Parent then
			connection:Disconnect()
			if push.Parent then
				push:Destroy()
			end
			return
		end
		u = math.max(u, 1e-3)
		local speed = distance / duration * (u ^ RUSH_A) * (1 - u) ^ RUSH_B / rushTotal
		push.PlaneVelocity = Vector2.new(direction.X, direction.Z) * speed
	end)
end

------------------------------------------------------------------------
-- Hover: holds a character in the air (slowly sinking) during juggles.
-- `delay` lets a launch carry them up first; each new call refreshes it.

local hoverTokens = setmetatable({}, { __mode = "k" })

function Motion.stopHover(root)
	hoverTokens[root] = (hoverTokens[root] or 0) + 1
	local existing = root:FindFirstChild("CombatHover")
	if existing then
		existing:Destroy()
	end
end

function Motion.hover(root, duration, delay)
	local token = (hoverTokens[root] or 0) + 1
	hoverTokens[root] = token

	local function begin()
		if hoverTokens[root] ~= token or not root.Parent then
			return
		end
		local hover = root:FindFirstChild("CombatHover")
		if not hover then
			hover = Instance.new("LinearVelocity")
			hover.Name = "CombatHover"
			hover.Attachment0 = getAttachment(root)
			hover.RelativeTo = Enum.ActuatorRelativeTo.World
			hover.VelocityConstraintMode = Enum.VelocityConstraintMode.Line
			hover.LineDirection = Vector3.yAxis
			hover.MaxForce = 6e4
			hover.Parent = root
		end
		hover.LineVelocity = -1.5
		task.delay(duration, function()
			if hoverTokens[root] == token and hover.Parent then
				hover:Destroy()
			end
		end)
	end

	if delay and delay > 0 then
		task.delay(delay, begin)
	else
		begin()
	end
end

-- One entry point for the server's Impulse remote. `orbit` is only used by
-- dashes (see Motion.dash).
function Motion.apply(root, kind, velocity, duration, delay, orbit)
	if kind == "push" then
		Motion.push(root, velocity, duration)
	elseif kind == "knockback" then
		Motion.knockback(root, velocity, duration)
	elseif kind == "dash" then
		Motion.dash(root, velocity, duration, orbit)
	elseif kind == "rush" then
		Motion.rush(root, velocity, duration)
	elseif kind == "stop" then
		Motion.stop(root)
	elseif kind == "hover" then
		Motion.hover(root, duration, delay)
	elseif kind == "stopHover" then
		Motion.stopHover(root)
	end
end

return Motion
]===]

SOURCES.AnimationData = [===[
--[[
	R6 fighting animations, authored as pose data. PoseAnimator plays them
	directly on the joints (no uploaded assets); AnimationBuilder can export
	any of them as a KeyframeSequence for the Animation Editor.

	Style: battlegrounds-style, deliberately overanimated. Every strike has
	a wind-up, a near-instant snap into the hit, a short hang on the impact
	pose, an overshoot on the way back and a settle into guard. The whole
	body sells each move: hips drop, the torso twists and steps in, the head
	counter-rotates to keep eyes on the target, the off hand chambers.

	Each joint pose is { pitch, yaw, roll, x, y, z } in degrees / studs,
	expressed in the parent part's space at the joint pivot:
	  Torso is relative to HumanoidRootPart, limbs and Head are relative to Torso.
	  pitch +  = limb swings forward/up (Torso: leans back, Head: looks up)
	  yaw   +  = turns left (on a hanging limb: twists it)
	  roll  +  = limb end swings toward +X (right); Torso/Head tilt left
	  x/y/z    = shift right / up / back (Torso translation moves the whole body)
	A limb's world angle is roughly the torso's pitch plus its own, so a torso
	leaning forward 30 needs its legs pitched +30 to stay vertical.

	Keys: motion runs on one smooth curve through all of a clip's keys (a
	monotone cubic, see the detailing pass): velocity carries through every
	key and only comes to rest where a joint reverses, so nothing snaps from
	pose to pose. Timing between keys is what shapes a move now. `ease`/`dir`
	are only used by AnimationBuilder's Animation Editor export.

	group:
	  base    - locomotion (Stance, Idle, Run, Jump, Fall), driven by the client
	  hold    - looping holds (block), stopped explicitly
	  action  - attacks, dashes, feints; replaces other action/react/hold tracks
	  react   - hit reactions and stuns; replaces action/react/hold tracks
	  overlay - plays on top without stopping anything

	holdLast: a non-looping clip that freezes on its last frame until stopped.
	trail:    which limbs get swing trails between the Swing and Hit markers.

	markers become KeyframeMarkers. `Hit` is the impact frame the server uses,
	`recover` is when the attacker can act again.
]]

------------------------------------------------------------------------
-- Shared poses

-- Fighting stance: sitting low on the legs, lead (left) shoulder forward,
-- rear fist at the chin, lead fist out front.
local GUARD = {
	Torso = { -8, -20, 0, 0, -0.2, 0 },
	Head = { 8, 18, 0 },
	RightArm = { 100, 0, -42, 0, 0, 0.1 },
	LeftArm = { 108, 0, 28, 0, 0, -0.05 },
	RightLeg = { 2, 0, 9 },
	LeftLeg = { 24, 0, -5 },
}

-- High guard: both gloves up side by side in front of the face (not
-- crossed), elbows tucked in, chin down behind them, shoulders hunched
-- forward. No legs, so the walk cycle keeps running underneath.
-- Guard pose, baked from Roblox animation 81591715877632 (upper body).
-- The legs live in BLOCK_LEGS and play under the run cycle (see Data.Block).
local BLOCK = {
	Torso = { -8.036, 0, 0 },
	Head = { 0, 0, 0 },
	RightArm = { 74.463, -26.082, -71.52 },
	LeftArm = { 96.088, 29.471, 76.579 },
}
local BLOCK_LEGS = {
	RightLeg = { 0, -8.192, 0, 0.055, 0, -0.385 },
	LeftLeg = { 0, 45.664, 0, -0.051, 0, 0.603 },
}

-- `base` with each joint's values shifted by `deltas` (same layout).
local function nudge(base, deltas)
	local result = {}
	for joint, value in pairs(base) do
		local d = deltas[joint]
		if d then
			local v = {}
			for i = 1, math.max(#value, #d) do
				v[i] = (value[i] or 0) + (d[i] or 0)
			end
			result[joint] = v
		 else
			result[joint] = value
		end
	end
	return result
end

-- Legs tucked under for air moves.
local AIR_LEGS = {
	RightLeg = { 46, 0, 8 },
	LeftLeg = { 14, 0, -8 },
}

local function pose(...)
	local result = {}
	for _, part in ipairs({ ... }) do
		for joint, value in pairs(part) do
			result[joint] = value
		end
	end
	return result
end

local MIRROR = {
	Torso = "Torso",
	Head = "Head",
	RightArm = "LeftArm",
	LeftArm = "RightArm",
	RightLeg = "LeftLeg",
	LeftLeg = "RightLeg",
}

-- Left/right mirror of a pose.
local function mirror(p)
	local result = {}
	for joint, v in pairs(p) do
		result[MIRROR[joint]] = { v[1], -(v[2] or 0), -(v[3] or 0), -(v[4] or 0), v[5] or 0, v[6] or 0 }
	end
	return result
end

local function mirrorKeys(keys)
	local result = {}
	for i, key in ipairs(keys) do
		result[i] = { t = key.t, ease = key.ease, dir = key.dir, pose = mirror(key.pose) }
	end
	return result
end

------------------------------------------------------------------------
-- Detailing pass
--
-- detail(clip, springs) resamples a clip along the smooth curve into dense keyframes (fps per
-- second) and runs the listed joints through damped springs while doing so:
-- they trail the joints that drive them and overshoot when those stop, i.e.
-- overlapping action and follow-through. Unlisted joints (the torso and the
-- striking limb) follow the authored poses exactly, so hit frames stay exact.
-- springs = { Joint = { frequency (Hz), damping ratio } }.

local function channels(value)
	return { value[1] or 0, value[2] or 0, value[3] or 0, value[4] or 0, value[5] or 0, value[6] or 0 }
end

-- Per joint: the authored keys with held values filled in, each with a
-- tangent per channel. Tangents follow the monotone cubic (PCHIP) rule:
-- velocity is continuous through every key, it only comes to rest where a
-- channel actually reverses, and the curve never overshoots between two
-- keys (the overshoots that sell a move are authored as keys of their own).
-- This replaces per-segment easing, which stopped the body dead on every
-- key and made moves read as a string of separate poses.
local function jointTracks(clip)
	local tracks = {}
	for _, key in ipairs(clip.keys) do
		for joint in pairs(key.pose) do
			tracks[joint] = tracks[joint] or {}
		end
	end
	local last = {}
	for _, key in ipairs(clip.keys) do
		for joint, list in pairs(tracks) do
			last[joint] = key.pose[joint] or last[joint] or { 0, 0, 0 }
			table.insert(list, { t = key.t, v = channels(last[joint]) })
		end
	end

	for _, list in pairs(tracks) do
		local n = #list
		for i, k in ipairs(list) do
			local prev, prevT = list[i - 1], nil
			local nxt, nextT = list[i + 1], nil
			if prev then
				prevT = prev.t
			elseif clip.looped and n > 2 then
				-- the last key repeats the first one, so wrap past it
				prev = list[n - 1]
				prevT = prev.t - clip.length
			end
			if nxt then
				nextT = nxt.t
			elseif clip.looped and n > 2 then
				nxt = list[2]
				nextT = nxt.t + clip.length
			end

			local m = { 0, 0, 0, 0, 0, 0 }
			if prev and nxt then
				local h0, h1 = k.t - prevT, nextT - k.t
				if h0 > 1e-6 and h1 > 1e-6 then
					for c = 1, 6 do
						local d0 = (k.v[c] - prev.v[c]) / h0
						local d1 = (nxt.v[c] - k.v[c]) / h1
						if d0 * d1 > 0 then
							local w1, w2 = 2 * h1 + h0, h1 + 2 * h0
							m[c] = (w1 + w2) / (w1 / d0 + w2 / d1)
						end
					end
				end
			end
			-- one-shots start from and settle into rest (m stays zero at the ends)
			k.m = m
		end
	end
	return tracks
end

local function sampleTrack(list, t)
	if t <= list[1].t then
		return table.clone(list[1].v)
	end
	for i = 1, #list - 1 do
		local a, b = list[i], list[i + 1]
		if t < b.t then
			local h = b.t - a.t
			local s = (t - a.t) / h
			local s2, s3 = s * s, s * s * s
			local h00 = 2 * s3 - 3 * s2 + 1
			local h10 = s3 - 2 * s2 + s
			local h01 = -2 * s3 + 3 * s2
			local h11 = s3 - s2
			local out = {}
			for c = 1, 6 do
				out[c] = h00 * a.v[c] + h10 * h * a.m[c] + h01 * b.v[c] + h11 * h * b.m[c]
			end
			return out
		end
	end
	return table.clone(list[#list].v)
end

local function detail(clip, springs, fps)
	fps = fps or 60
	local tracks = jointTracks(clip)
	local length = clip.length

	-- output times: an even grid plus every authored key and marker
	local times, seen = {}, {}
	local function addTime(t)
		local k = math.floor(t * 10000 + 0.5)
		if not seen[k] then
			seen[k] = true
			table.insert(times, k / 10000)
		end
	end
	for i = 0, math.floor(length * fps) do
		addTime(i / fps)
	end
	for _, key in ipairs(clip.keys) do
		addTime(key.t)
	end
	for _, t in pairs(clip.markers or {}) do
		addTime(t)
	end
	addTime(length)
	table.sort(times)

	-- springs, warmed up over a full extra cycle for loops
	local state = {}
	for joint, params in pairs(springs) do
		if tracks[joint] then
			state[joint] = { x = sampleTrack(tracks[joint], 0), v = { 0, 0, 0, 0, 0, 0 }, w = params[1] * 2 * math.pi, z = params[2] }
		end
	end
	local h = 1 / 480
	local clock = clip.looped and -length or 0
	local function advance(toTime)
		while clock < toTime - 1e-9 do
			local step = math.min(h, toTime - clock)
			clock += step
			local t = clock % length
			if not clip.looped then
				t = math.clamp(clock, 0, length)
			end
			for joint, sp in pairs(state) do
				local target = sampleTrack(tracks[joint], t)
				for c = 1, 6 do
					local accel = sp.w * sp.w * (target[c] - sp.x[c]) - 2 * sp.z * sp.w * sp.v[c]
					sp.v[c] += accel * step
					sp.x[c] += sp.v[c] * step
				end
			end
		end
	end

	local keys = {}
	for _, t in ipairs(times) do
		advance(t)
		local p = {}
		for joint, list in pairs(tracks) do
			local exact = sampleTrack(list, t)
			local sp = state[joint]
			if sp then
				-- ease back onto the authored pose at the very end of one-shots
				local blend = clip.looped and 0 or math.clamp((t - (length - 0.12)) / 0.12, 0, 1) ^ 2
				local v = {}
				for c = 1, 6 do
					v[c] = sp.x[c] + (exact[c] - sp.x[c]) * blend
				end
				p[joint] = v
			else
				p[joint] = exact
			end
		end
		table.insert(keys, { t = t, ease = "Linear", pose = p })
	end
	if clip.looped then
		keys[#keys].pose = keys[1].pose -- seamless seam
	end

	local result = table.clone(clip)
	result.keys = keys
	result.sourceKeys = clip.keys
	return result
end

-- Pushes every in-between pose further from the clip's first pose (bigger
-- arm arcs, deeper dips, longer lunges); the first and last keys stay put.
-- Torso yaw and the legs are left alone: in R6 the legs hang off the torso,
-- so extra twist would swing the feet sideways.
local KEEP = { RightLeg = true, LeftLeg = true }

local function exaggerate(clip, amount)
	local first = clip.keys[1].pose
	local keys = {}
	for i, key in ipairs(clip.keys) do
		if i == 1 or i == #clip.keys then
			keys[i] = key
		else
			local p = {}
			for joint, value in pairs(key.pose) do
				local base = channels(first[joint] or { 0, 0, 0 })
				local v = channels(value)
				if not KEEP[joint] then
					for c = 1, 6 do
						if not (joint == "Torso" and c == 2) then
							v[c] = base[c] + (v[c] - base[c]) * amount
						end
					end
				end
				p[joint] = v
			end
			keys[i] = { t = key.t, ease = key.ease, dir = key.dir, pose = p }
		end
	end
	local result = table.clone(clip)
	result.keys = keys
	return result
end

local AIR_GUARD = pose(GUARD, AIR_LEGS, { Torso = { -4, -14, 0 } })

-- GUARD without the legs, for overlays that leave the lower body alone.
local GUARD_UPPER = {
	Torso = GUARD.Torso,
	Head = GUARD.Head,
	RightArm = GUARD.RightArm,
	LeftArm = GUARD.LeftArm,
}

local Config = require(script.Parent.Config)

local Data = {}

------------------------------------------------------------------------
-- Locomotion

-- Fighter's bounce: weight dips and rises on the balls of the feet, the
-- shoulders roll and the fists bob out of phase so the guard never freezes.
-- Fighting stance, alive: four bounces on the balls of the feet per loop,
-- each a little different. The body springs off the floor (fast out of the
-- dip, floating at the top), weight drifts from foot to foot, the shoulders
-- roll, the rear fist circles at the chin while the lead fist paws forward
-- out of phase, and the head steadies itself with a glance halfway through.
-- Feet stay planted: leg angles counter the torso's dip, tilt and sway.
Data.Stance = {
	length = 2, looped = true, priority = "Idle", group = "base",
	keys = {
